const bankQrHost="// Same-origin transport; identity always comes from the server session.\nconst RpaBankQrHost=(()=>{\n const selection=()=>typeof ensureReportDateState==='function'&&['notes','report','personal'].includes(tab)?ensureReportDateState().scope:(typeof scope==='string'?scope:'all');\n const actor=()=>D?.user?.active===true?D.user.id:null;\n async function request(path,{method='GET',body}={}){\n  const expected=actor();if(!expected)throw new Error('SIGNED_OUT');\n  const headers={'X-RPA-Actor':expected};\n  if(method==='PUT'){\n   const csrfResponse=await fetch('/api/csrf',{credentials:'same-origin',cache:'no-store'});\n   const csrf=await csrfResponse.json();\n   if(!csrfResponse.ok||csrf.success!==true||typeof csrf.data?.csrfToken!=='string'||actor()!==expected)throw new Error('CSRF_UNAVAILABLE');\n   headers['Content-Type']='application/json';headers['X-CSRF-Token']=csrf.data.csrfToken;\n  }\n  if(actor()!==expected)throw new Error('ACCOUNT_CHANGED');\n  const response=await fetch(path,{method,headers,body:body?JSON.stringify(body):undefined,credentials:'same-origin',cache:'no-store'});\n  const result=await response.json();\n  if(actor()!==expected)throw new Error('ACCOUNT_CHANGED');\n  if(!response.ok||result.success!==true){const error=new Error('PROFILE_REQUEST_FAILED');error.code=result.error?.code;throw error;}\n  return result.data;\n }\n const feature=RpaBankQr.createBankQrFeature({getContext:()=>({actorId:actor(),active:!!actor()}),api:{\n  readOwn:()=>request('/api/bank-profile'),\n  saveOwn:body=>request('/api/bank-profile',{method:'PUT',body}),\n  readCreditor:id=>{const bounds=range();const query=new URLSearchParams({start:bounds.start,end:bounds.end,scope:selection()});return request('/api/users/'+encodeURIComponent(id)+'/bank-profile?'+query);}\n }});\n let previousView=null,previousGroups=null;\n function sync(){\n  feature.syncSession();\n  const view=JSON.stringify([actor(),tab,selection(),D?.notes,typeof range==='function'&&['notes','report','personal'].includes(tab)?range():null]);\n  if(view!==previousView){feature.close();previousView=view;}\n }\n function mount(){\n  sync();if(!actor()||tab!=='local-settings')return;\n  const settings=document.querySelector('.local-member-settings');if(!settings)return;\n  let root=document.getElementById('rpa-bank-profile-settings');\n  if(!root){root=document.createElement('div');root.id='rpa-bank-profile-settings';settings.after(root);void feature.mountSettings(root);}\n }\n function decorate(root,result,mode){\n  sync();const groupsView=JSON.stringify([actor(),tab,mode,result]);if(groupsView!==previousGroups){feature.close();previousGroups=groupsView;}\n  if(result.status!=='ok'||mode!=='pay')return;\n  void feature.decoratePayGroups({root,groups:result.pay.groups,direction:'pay'});\n }\n const previousRender=render;\n render=function(...args){feature.close();sync();const result=previousRender(...args);mount();return result;};\n return Object.freeze({decorate,mount,sync});\n})();\n";
const bankQrCss=".rpa-bank-settings{margin-top:18px;padding:16px;border:1px solid #d5e2d9;border-radius:14px;background:white}\n.rpa-bank-settings p,.rpa-bank-settings small{display:block;font-size:13px;line-height:1.5;color:#52675c}\n.rpa-bank-settings label{display:grid;gap:5px;margin:12px 0}\n.rpa-bank-settings input,.rpa-bank-settings select{box-sizing:border-box;width:100%;min-width:0;padding:10px;border:1px solid #c9d8cf;border-radius:8px;font:inherit}\n.bank-qr-actions{display:flex;gap:8px;flex-wrap:wrap}\n.bank-qr-actions button{padding:10px 14px;border-radius:8px;border:0;background:#246951;color:white}\n.bank-qr-actions button:disabled{opacity:.5}\n.rpa-bank-qr-icon{flex:none!important;display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;padding:5px;border:1px solid #ccded2;border-radius:7px;background:white;color:#246951}\n.rpa-bank-qr-icon:focus-visible{outline:2px solid #246951;outline-offset:2px}\n.rpa-bank-qr-dialog{box-sizing:border-box;width:min(380px,calc(100vw - 24px));max-height:calc(100vh - 32px);padding:20px;border:0;border-radius:16px;text-align:center;overflow:auto;color:#193e30}\n.rpa-bank-qr-dialog::backdrop{background:#10251aaa}\n.rpa-bank-qr-dialog .qr-close{box-sizing:border-box;float:right;display:inline-flex;align-items:center;justify-content:center;flex:0 0 44px;width:44px;min-width:44px;max-width:44px;height:44px;min-height:44px;max-height:44px;padding:0;line-height:1;border:0;border-radius:7px;background:#edf5f0;color:#246951}\n.rpa-bank-qr-dialog img{display:block;width:100%;height:auto;max-width:300px;margin:0 auto;cursor:default}\n.rpa-bank-qr-dialog .bank-account{overflow-wrap:anywhere;font-size:18px;font-weight:600}\n.rpa-bank-qr-dialog small{display:block;line-height:1.5;margin-top:10px;color:#52675c}\n.bank-qr-stage{min-height:280px;display:grid;place-items:center}\n.bank-qr-loading{display:grid;justify-items:center;gap:14px;padding:36px 12px}\n.bank-qr-spinner{display:block;width:32px;height:32px;border:4px solid #d9e8de;border-top-color:#246951;border-radius:50%;animation:rpa-qr-spin 1s linear infinite}\n.bank-qr-share{display:block;width:100%;padding:0;border:0;background:white;cursor:pointer;border-radius:8px}\n.bank-qr-share:focus-visible{outline:3px solid #246951;outline-offset:3px}\n.rpa-bank-qr-dialog .bank-qr-share img{cursor:pointer}\n.bank-qr-download,.bank-qr-stage button:not(.bank-qr-share){padding:10px 14px;border:0;border-radius:8px;background:#246951;color:white;font:inherit}\n@keyframes rpa-qr-spin{to{transform:rotate(360deg)}}\n@media(prefers-reduced-motion:reduce){.bank-qr-spinner{animation:none}}\n\n.rpa-bank-qr-dialog .qr-close svg{display:block;flex:none;width:20px;height:20px;margin:0;pointer-events:none}\n.rpa-bank-qr-dialog .qr-close:focus-visible{outline:2px solid #246951;outline-offset:2px}\n";
